using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
sealed class ElfSection {public long Address;public int Size,Raw,Type,Link,Entry;public ulong Flags;}
sealed class ElfSymbol {public long Address;public int Size;}
sealed class ElfImage {
 public readonly byte[] Bytes;public const long ImageBase=0x20000000;public readonly List<ElfSection> Sections=new List<ElfSection>();readonly Dictionary<string,ElfSymbol> symbols=new Dictionary<string,ElfSymbol>(StringComparer.Ordinal);
 void Check(long offset,long count){if(offset<0||count<0||offset>Bytes.LongLength-count)throw new IOException("Invalid ELF bounds.");}
 ushort U16(int at){Check(at,2);return BitConverter.ToUInt16(Bytes,at);}int I32(int at){Check(at,4);return BitConverter.ToInt32(Bytes,at);}long I64(int at){Check(at,8);return BitConverter.ToInt64(Bytes,at);}
 string Name(int at,int end){if(at<0||at>=end||end>Bytes.Length)throw new IOException("Invalid ELF symbol name.");int stop=at;while(stop<end&&Bytes[stop]!=0&&stop-at<2048)stop++;if(stop==end||stop-at>=2048)throw new IOException("Unterminated ELF symbol.");return Encoding.UTF8.GetString(Bytes,at,stop-at);}
 public ElfImage(byte[] bytes){Bytes=bytes;if(bytes.Length<64||bytes.Length>300*1024*1024||bytes[0]!=127||bytes[1]!=69||bytes[2]!=76||bytes[3]!=70||bytes[4]!=2||bytes[5]!=1||U16(16)!=2||U16(18)!=62)throw new IOException("Select a native Linux x86-64 ELF executable.");long table=I64(40);int size=U16(58),count=U16(60);if(size!=64||count<1||count>4096)throw new IOException("Invalid ELF section table.");Check(table,(long)count*size);
 for(int i=0;i<count;i++){int at=checked((int)(table+i*size));long raw=I64(at+24),length=I64(at+32);if(raw<0||length<0||raw>int.MaxValue||length>int.MaxValue)throw new IOException("Invalid ELF section size.");var section=new ElfSection {Address=I64(at+16),Size=(int)length,Raw=(int)raw,Type=I32(at+4),Flags=(ulong)I64(at+8),Link=I32(at+40),Entry=checked((int)I64(at+56))};if(section.Type!=8)Check(raw,length);Sections.Add(section);}
 foreach(var section in Sections.Where(x=>x.Type==2||x.Type==11)){if(section.Link<0||section.Link>=Sections.Count||section.Entry!=24||section.Size%24!=0)throw new IOException("Invalid ELF symbols.");var strings=Sections[section.Link];for(int at=section.Raw;at<section.Raw+section.Size;at+=24){int name=I32(at);ushort index=U16(at+6);long value=I64(at+8),length=I64(at+16);if(index==0||index>=Sections.Count||name<0||name>=strings.Size||value< ImageBase||value>=0x30000000||length<0||length>int.MaxValue)continue;string text=Name(strings.Raw+name,strings.Raw+strings.Size);if(text.Length>0)symbols[text]=new ElfSymbol {Address=value,Size=(int)length};}}
 if(symbols.Count<100)throw new IOException("ELF symbols are unavailable; this build cannot be recognized automatically.");}
 public long Symbol(string name){if(name=="$image")return ImageBase;ElfSymbol result;if(!symbols.TryGetValue(name,out result))throw new IOException("Missing ELF symbol: "+name);return result.Address;}
 public int FunctionLength(string name){return symbols.ContainsKey(name)?symbols[name].Size:0;}
 public byte[] Read(long address,int count){foreach(var section in Sections)if(section.Type!=8&&address>=section.Address&&address+count<=section.Address+section.Size){int raw=checked(section.Raw+(int)(address-section.Address));Check(raw,count);var result=new byte[count];Buffer.BlockCopy(Bytes,raw,result,0,count);return result;}throw new IOException("ELF address is outside file-backed sections.");}
 public bool ReadOnly(long address,int count){return Sections.Any(section=>section.Type!=8&&address>=section.Address&&address+count<=section.Address+section.Size&&(section.Flags&5)==0);}
 public static string Hash(byte[] bytes){using(var hash=SHA256.Create())return Program.Hex(hash.ComputeHash(bytes));}
}
public sealed class LinuxReference {public int offset,width,addend,bias;public string symbol,kind,data_expected;}
public sealed class LinuxSignature {public string name,expected,mask;public int length;public LinuxReference[] references;}
public sealed class LinuxMetadata {public int format,trampoline_length,online_addend;public string baseline_game_sha256,online_symbol;public string[] runtime_symbols,globals;public LinuxSignature[] functions;}
static class LinuxCompatibility {
 static IOException Changed(string name){Program.SessionLog("Changed Linux native interface: "+name);return new IOException(UiLanguage.Text("Esta versão do jogo não é compatível. Nenhum jogo foi iniciado ou alterado."));}
 public static void Resolve(string path,Profile profile){var image=new ElfImage(File.ReadAllBytes(path));IOException last=null;foreach(string file in new[]{"compatibility-linux.json","compatibility-linux-legacy.json"}){try{var metadata=new JavaScriptSerializer {MaxJsonLength=8*1024*1024}.Deserialize<LinuxMetadata>(File.ReadAllText(Path.Combine(Program.Root,file)));ResolveImage(image,profile,metadata);return;}catch(IOException error){last=error;}}throw last??Changed("metadata");}
 public static void ResolveImage(ElfImage image,Profile profile,LinuxMetadata metadata){if(metadata.format!=3||metadata.functions==null||metadata.functions.Length<50||metadata.runtime_symbols==null||metadata.runtime_symbols.Length!=30||metadata.trampoline_length!=6)throw Changed("metadata");var report=new StringBuilder();report.AppendLine("Strict Linux ELF instruction signatures, symbolic targets and literal contents.");report.AppendLine("Game SHA256: "+ElfImage.Hash(image.Bytes));
 foreach(var signature in metadata.functions){long address=image.Symbol(signature.name);var expected=Program.Unhex(signature.expected);var mask=Program.Unhex(signature.mask);if(signature.length!=expected.Length||mask.Length!=expected.Length||signature.length<5||image.FunctionLength(signature.name)!=signature.length)throw Changed(signature.name+" length");var actual=image.Read(address,signature.length);for(int i=0;i<actual.Length;i++)if((actual[i]&mask[i])!=(expected[i]&mask[i]))throw Changed(signature.name+" + "+i);
 foreach(var reference in signature.references){if(reference.offset<0||reference.width!=4&&reference.width!=8||reference.offset+reference.width>actual.Length)throw Changed("reference bounds");long value=reference.width==4?BitConverter.ToInt32(actual,reference.offset):BitConverter.ToInt64(actual,reference.offset);long target=reference.kind=="relative"?address+reference.offset+reference.bias+value:value;if(!string.IsNullOrEmpty(reference.data_expected)){byte[] content=Program.Unhex(reference.data_expected);if(!image.ReadOnly(target,content.Length)||!image.Read(target,content.Length).SequenceEqual(content))throw Changed(signature.name+" literal");}else if(target!=image.Symbol(reference.symbol)+reference.addend)throw Changed(signature.name+" target "+reference.symbol);}
 report.AppendLine("PASS "+signature.name);}
 if(Program.Hex(image.Read(image.Symbol("Port_PadRead"),6))!="f30f1efa4157")throw Changed("pad trampoline");var globals=new Dictionary<string,int>();foreach(string name in metadata.globals)if(name!="online_mode")globals[name]=checked((int)(image.Symbol(name)-ElfImage.ImageBase));globals["online_mode"]=checked((int)(image.Symbol(metadata.online_symbol)+metadata.online_addend-ElfImage.ImageBase));profile.symbols=globals;profile.runtime_addresses=metadata.runtime_symbols.Select(name=>image.Symbol(name)).ToArray();profile.game_sha256=ElfImage.Hash(image.Bytes);File.WriteAllText(Path.Combine(Program.Root,"compatibility-report.txt"),report.ToString());}
}
